contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(c).balance, "amount must not exceed C's balance");
        uint beforeBalC = address(c).balance;
        uint beforeBalThis = address(this).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint afterBalC = address(c).balance;
        uint afterBalThis = address(this).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(afterBalC == beforeBalC - amount && afterBalThis == beforeBalThis + amount && afterCount == beforeCount);
    }

    receive() external payable {}
}

